// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // Keep depositor as a non-zero address and amount within reasonable ETH bounds
        vm.assume(depositor != address(0));
        // bound amount to a sane range so vm.deal works comfortably
        amount = bound(amount, 0, 1 ether);

        // Ensure depositor has funds to send
        vm.deal(depositor, amount);

        // First deposit: call receive from depositor with amount
        vm.prank(depositor);
        // If amount is zero, still a valid call to receive must be possible (receive executes on empty calldata only if msg.value>0 or is payable fallback?)
        // In Solidity, receive() is called when msg.data is empty (works even for 0 value). We simulate sending amount.
        (bool ok1, ) = address(c).call{value: amount}("");
        // After a successful call to receive, the reference contract guarantees depositsCount >= 1
        // We assert using the public getter depositsCount()
        // This single assertion must hold for the reference for all inputs; the mutant will fail for some inputs (when depositsCount was nonzero)
        assertTrue(c.depositsCount() >= 1);
    }
}

