pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: sender address and amount to send
    function testFuzz_property(address sender, uint256 amount) public {
        // keep sender as a nonzero address (EOA) and amount > 0 and bounded to reasonable value
        vm.assume(sender != address(0));
        amount = bound(amount, 1, 1 ether);

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        // first deposit: ensure depositCount increases from initial 0 to 1
        vm.prank(sender);
        (bool ok1, ) = address(c).call{value: amount}("");
        // calling receive should succeed on both reference and mutant for empty initial depositsCount
        require(ok1, "initial deposit failed");
        uint before = c.depositsCount();

        // second deposit: perform another deposit from possibly different sender/address and amount
        // use same fuzzed sender and amount to keep inputs parameterized
        vm.deal(sender, amount);
        vm.prank(sender);
        (bool ok2, ) = address(c).call{value: amount}("");
        // the reference contract will increment depositsCount again so after > before
        // for the reference, ok2 should be true; for mutant ok2 can still be true but depositsCount won't increase
        require(ok2, "second deposit failed");

        uint after = c.depositsCount();

        // General rule (single assertion): after a deposit call, depositsCount strictly increases
        // We assert that after > before. The reference satisfies this for all admissible inputs; the mutant fails for some (when before != 0).
        assertTrue(after > before);
    }
}

