pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz the sender and the amount sent
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount within a reasonable bound (but wide)
        amount = bound(amount, 0, 1 ether);

        // make sure sender has ETH to send
        vm.deal(sender, amount);

        // call C.receive() by sending plain ETH to the contract from sender
        bool ok;
        uint before = c.depositsCount();
        vm.prank(sender);
        // use low-level call to trigger receive; capture success via try/catch on payable call
        // solidity does not allow try on plain transfer; instead use an external call to address
        // we perform the call via (bool success, ) = address(c).call{value: amount}("");
        // but the test requirement asks to observe via try/catch pattern when revert differences exist.
        // We emulate that by wrapping the low-level call result into ok.
        (bool success, ) = address(c).call{value: amount}("");
        ok = success;

        // The general property: for all admissible inputs, the correct contract's receive succeeds
        // and increments depositsCount by 1. We assert that the call succeeded.
        // On the mutant (which revert always), some inputs (any positive amount) will make success==false.
        assertTrue(ok == true);

        // Also ensure depositsCount actually incremented (observational check through public getter)
        // This additional check is allowed because it's reading c's public surface.
        uint after = c.depositsCount();
        assertTrue(after == before + 1);
    }
}

