pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: an arbitrary sender and an arbitrary amount of wei
    function testFuzz_property(address sender, uint256 amount) public {
        // keep amount in a wide admissible domain but avoid trivial zero-value which doesn't exercise deposit behavior
        vm.assume(sender != address(0));
        amount = bound(amount, 0, 1 ether);

        // fund the sender so it can send ETH
        vm.deal(sender, amount);

        // perform the external payable send to C through the receive fallback as the sender
        bool ok;
        vm.prank(sender);
        try c.call{value: amount}("") {
            // low-level call succeeded
            ok = true;
        } catch {
            // low-level call reverted
            ok = false;
        }

        // The universal property: when the low-level payable call succeeds, the depositsCount should have increased by 1
        // Read depositsCount via the public getter. We assert that if the call succeeded then depositsCount > 0
        // (since c was new and depositsCount starts at 0). This holds for the reference contract for all admissible inputs,
        // while the mutant that does `require(false)` in receive will cause the call to revert for positive amounts,
        // making ok == false for those inputs.
        if (ok) {
            assertTrue(c.depositsCount() > 0);
        } else {
            // If the call reverted, depositsCount must remain 0 (still a valid observation of C). We assert that
            // either the call succeeded and depositsCount increased, or the call failed. This single assertTrue
            // checks the meaningful observable relation: ok implies depositsCount>0.
            // To satisfy the single-assert requirement in the problem statement, we fold into one assertion below.
            assertTrue(!(ok) || (c.depositsCount() > 0));
        }
    }
}

