pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: a caller address and an amount of ETH to send
    function testFuzz_property(address actor, uint256 amount) public {
        // keep amount in a reasonable range (0 .. 1 ether) but allow zero so property is universal
        amount = bound(amount, 0, 1 ether);
        // avoid using the contract's deployer as actor to ensure msg.sender differences
        vm.assume(actor != address(0));

        // fund the actor so they can send ETH
        vm.deal(actor, amount);

        // record depositsCount and balance before
        uint beforeCount = c.depositsCount();
        uint beforeBal = address(c).balance;

        bool ok;
        // perform the payable send to trigger receive()
        vm.prank(actor);
        try c.call{value: amount}("") {
            // if low-level call returned (no revert), mark ok true
            ok = true;
        } catch {
            ok = false;
        }

        uint afterCount = c.depositsCount();
        uint afterBal = address(c).balance;

        // General rule: For any caller and any nonzero amount, the reference contract accepts the funds
        // (call succeeds), increases depositsCount by 1, and contract balance increases by amount.
        // The mutant that does `require(false)` in receive() will cause the call to revert for some inputs
        // (e.g., any positive amount), breaking this rule.
        if (amount == 0) {
            // sending 0 may or may not increment depending on semantics; require that behavior is non-decreasing
            assertTrue(afterCount >= beforeCount);
        } else {
            // For positive amounts, reference: call succeeds and counts/balance increase exactly by 1/amount
            assertTrue(ok && afterCount == beforeCount + 1 && afterBal == beforeBal + amount);
        }
    }
}

