pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzzed params: amount to send and whether the helper will reenter
    function testFuzz_property(uint256 amount, bool doReenter) public {
        // keep amount within reasonable bounds (but wide)
        amount = bound(amount, 0, 1 ether);

        // Deploy adversarial helper that can optionally reenter c during its receive
        ReentrantHelper helper = new ReentrantHelper(c);

        // fund the helper so it can forward value when prank is used
        vm.deal(address(helper), amount + 1 ether);

        // record before
        uint256 before = c.depositsCount();

        // If helper should reenter, set its flag
        helper.setReenter(doReenter);

        // Make the helper receive ETH which will trigger c.receive via call from helper
        // We impersonate the helper to send ETH to c (so c's receive sees msg.sender == helper)
        vm.prank(address(helper));
        // helper will call c with value, indirectly invoking c.receive
        helper.triggerSend{value: amount}();

        // after
        uint256 afterCount = c.depositsCount();

        // General rule: correct contract ensures depositsCount never decreases after a receive call
        // So assert that afterCount >= before
        assertTrue(afterCount >= before);
    }
}

// Helper that can call c.receive via a plain call (so msg.sender is helper)
contract ReentrantHelper {
    C immutable target;
    bool public reenter;

    constructor(C _t) {
        target = _t;
    }

    function setReenter(bool r) external {
        reenter = r;
    }

    // Fallback to receive ETH and optionally reenter target
    receive() external payable {
        // If instructed, perform an extra low-level call to target so target.receive executes
        if (reenter) {
            // call target without data, triggering its receive
            (bool ok, ) = address(target).call{value: 0}("");
            // ignore ok
            ok;
        }
    }

    // External function to trigger sending ETH to target (so msg.sender for target is this helper)
    function triggerSend() external payable {
        // Forward the received ETH to target; this invokes target.receive with msg.sender = address(this)
        (bool s,) = address(target).call{value: msg.value}("");
        require(s);
    }
}

