pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed parameters: amount sent and an initial depositsCount seed (as unsigned to attempt to drive wrap behavior)
    function testFuzz_property(uint256 sendAmt, uint256 seed) public {
        // keep domains wide but admissible: sendAmt must be non-zero and not exceed some large bound
        vm.assume(sendAmt > 0);
        // seed used to drive the attacker's behavior; keep it within u256

        // deploy attacker that will reenter C.receive and try to increment depositsCount multiple times
        Attacker attacker = new Attacker(address(c));

        // fund the attacker so it can send ETH to c in its attack
        vm.deal(address(attacker), sendAmt * 3 + 1);

        // set an initial depositsCount by making some benign deposits as the test contract
        // use vm.prank to send from this contract (msg.sender will be this test contract) - but C.owner was set to deployer (test contract), so that's fine
        // first create some baseline deposits by calling receive through direct transfers
        // perform 'seed' number of small deposits to influence depositsCount (but bound seed to reasonable number to avoid long loops)
        uint256 boundedSeed = bound(seed, 0, 20);
        for (uint256 i = 0; i < boundedSeed; i++) {
            // send 1 wei from this test contract into c to increment depositsCount legitimately
            payable(address(c)).transfer({value: 1});
        }

        // record previous depositsCount
        uint256 before = c.depositsCount();

        // Now let attacker perform a call that will reenter C.receive and attempt to create a scenario where mutant's unguarded increments lead to a decrease (via wrap or reentrancy interplay).
        // The attacker will call C by sending sendAmt value; this triggers attacker.receive which reenters c via additional small transfers.
        attacker.attack{value: sendAmt}(sendAmt);

        // single assertion: in the correct contract depositsCount must not decrease after the receive-driven interaction
        uint256 after = c.depositsCount();
        assertTrue(after >= before);
    }
}

// Minimal adversarial contract: on receiving ETH, it reenters C by sending small transfers multiple times
contract Attacker {
    address immutable target;
    uint256 public reenterCount;

    constructor(address _target) {
        target = _target;
    }

    // attack entry: send initial call value and set how many reentries to perform
    function attack(uint256 /*unused*/) external payable {
        // store a reenter count to guide fallback
        reenterCount = 3;
        // initial transfer triggers target.receive
        // nothing else needed; funds are sent via this payable call
    }

    receive() external payable {
        // on first entry, reenter target a few times by forwarding tiny amounts
        if (reenterCount > 0) {
            reenterCount--;
            // perform a small transfer to reenter target.receive
            (bool ok, ) = target.call{value: 1}("");
            // ignore success to mimic a malicious caller that doesn't care
            ok;
        }
    }
}

